                            seen.add((ny, nx))
                            stack.append((ny, nx))
            comps.append(comp)

    if not comps:
        return g

    # The track selected for recoloring is the largest connected track.
    track = max(comps, key=len)
    selected_markers = set()

    # Include marker-colored cells touching that track.
    for r, c in track:
        for dy in (-1, 0, 1):
