def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Use the direction with more repeated-color lines.
    def line_data(horizontal):
        nlines = h if horizontal else w
        length = w if horizontal else h
        lines = []
        count = 0
        for k in range(nlines):
            vals = [grid[k][i] if horizontal else grid[i][k] for i in range(length)]
            lines.append(vals)
            if any(sum(v == c for v in vals) >= 2 for c in set(vals) if c != 0):
                count += 1
        return lines, count

    rows, nr = line_data(True)
    cols, nc = line_data(False)
    horizontal = nr > nc
    lines = rows if horizontal else cols

    for k, vals in enumerate(lines):
        length = len(vals)
        colors = {v for v in vals if v != 0}
        for color in colors:
            pos = [i for i, v in enumerate(vals) if v == color]
            if len(pos) < 2:
                continue

            period = 0
            for a, b in zip(pos, pos[1:]):
                period = gcd(period, b - a)
            residue = pos[0] % period
            lo, hi = min(pos), max(pos)

            outside = [
                (i, vals[i]) for i in range(length)
                if i % period == residue and vals[i] not in (0, color)
                and (i < lo or i > hi)
            ]
            other_colors = {v for _, v in outside}
            target = None
            if len(other_colors) == 1:
                sides = {("left" if i < lo else "right") for i, _ in outside}
                if len(sides) == 1:
                    side = next(iter(sides))
                    candidates = [i for i, _ in outside]
                    target = (max(candidates) if side == "left" else min(candidates),
                              next(iter(other_colors)), side)

            for i in range(length):
                if i % period != residue:
                    continue
                if target is None:
                    if vals[i] == 0:
                        if horizontal:
                            out[k][i] = color
                        else:
                            out[i][k] = color
                else:
                    stop, new_color, side = target
                    within = i >= stop if side == "left" else i <= stop
                    if within:
                        if horizontal:
                            out[k][i] = new_color
                        else:
                            out[i][k] = new_color

    return out

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Locate the solid, single-color divider.
    divider = None
    for c in range(w):
        vals = {grid[r][c] for r in range(h)}
        if len(vals) == 1 and 0 not in vals:
            divider = ("v", c)
            break
    if divider is None:
        for r in range(h):
            vals = set(grid[r])
            if len(vals) == 1 and 0 not in vals:
                divider = ("h", r)
                break
    if divider is None:
        return out

    orient, b = divider
    count = h if orient == "v" else w
    length = w if orient == "v" else h

    for i in range(count):
        line = [grid[i][j] for j in range(length)] if orient == "v" else [grid[j][i] for j in range(length)]

        left = any(line[j] != 0 for j in range(b))
        right = any(line[j] != 0 for j in range(b + 1, length))
        if left == right:
            continue

        toward_right = left
        lo, hi = (0, b) if toward_right else (b + 1, length)
        positions = range(lo, hi)
        runs = []
        j = lo
        while j < hi:
            if line[j] == 0:
                j += 1
                continue
            color = line[j]
            start = j
            while j < hi and line[j] == color:
                j += 1
            runs.append((start, j - 1, color))

        if not runs:
            continue

        if toward_right:
            near = sorted(runs, key=lambda x: x[1], reverse=True)
            touches = line[b - 1] != 0
            target = range(b + 1, length)
        else:
            near = sorted(runs, key=lambda x: x[0])
            touches = line[b + 1] != 0
            target = range(b - 1, -1, -1)

        def put(pos, color):
            if orient == "v":
                out[i][pos] = color
            else:
                out[pos][i] = color

        # A single-cell segment touching the divider carries straight through.
        if touches and near[0][1] - near[0][0] + 1 == 1:
            for p in target:
                put(p, near[0][2])
            continue

        # Two-color pattern with a gap before the divider.
        if (not touches and len(near) == 2
                and near[0][1] - near[0][0] + 1 == 2
                and near[1][1] - near[1][0] + 1 == 1):
            for k, p in enumerate(target):
                put(p, near[k % 2][2])
            continue

        # Each segment repeats at intervals equal to its length.
        # Farther segments are drawn first so nearer ones take precedence.
        for start, end, color in reversed(near):
            period = end - start + 1
            for k, p in enumerate(target, start=1):
                if k % period == 1 % period:
                    put(p, color)

    return out

