def transform(grid):
    from collections import deque

    H, W = len(grid), len(grid[0])
    seen = set()
    comps = []
    for r in range(H):
        for c in range(W):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x, grid[y][x]))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < H and 0 <= nx < W and
                            grid[ny][nx] != 0 and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        q.append((ny, nx))
            comps.append(cells)

    pieces = []
    anchor = None
    for cells in comps:
        colors = [v for _, _, v in cells if v != 5]
        if not colors:
            continue
        color = max(set(colors), key=colors.count)
        vals = {(r, c): (5 if v == 5 else color) for r, c, v in cells}
        minr = min(r for r, c in vals)
        minc = min(c for r, c in vals)
        shape = {(r - minr, c - minc): v for (r, c), v in vals.items()}
        item = (color, shape)
        pieces.append(item)
        if any(v == 5 for v in shape.values()):
            anchor = len(pieces) - 1

    if anchor is None:
        return [row[:] for row in grid]

    area = sum(len(shape) for _, shape in pieces)
    n = int(area ** 0.5)
    if n * n != area:
        return [row[:] for row in grid]
    full = (1 << area) - 1

    def rotate(shape):
        h = max(r for r, c in shape) + 1
        new = {(c, h - 1 - r): v for (r, c), v in shape.items()}
        mr = min(r for r, c in new)
        mc = min(c for r, c in new)
        return {(r - mr, c - mc): v for (r, c), v in new.items()}

    def orientations(shape):
        result = []
        cur = shape
        seen_shapes = set()
        for _ in range(4):
            key = tuple(sorted((r, c, v) for (r, c), v in cur.items()))
            if key not in seen_shapes:
                seen_shapes.add(key)
                result.append(cur)
            cur = rotate(cur)
        return result

    orients = [orientations(shape) for _, shape in pieces]
    placements = [[] for _ in pieces]
    bycell = [[[] for _ in range(area)] for _ in pieces]

    for pi, forms in enumerate(orients):
        unique = set()
        for form in forms:
            h = max(r for r, c in form) + 1
            w = max(c for r, c in form) + 1
            for oy in range(n - h + 1):
                for ox in range(n - w + 1):
                    entries = tuple(sorted((oy + r, ox + c, v)
                                           for (r, c), v in form.items()))
                    key = entries
                    if key in unique:
                        continue
                    unique.add(key)
                    mask = 0
                    indexed = []
                    for r, c, v in entries:
                        idx = r * n + c
                        mask |= 1 << idx
                        indexed.append((idx, v))
                    pid = len(placements[pi])
                    placements[pi].append((mask, indexed))
                    for idx, _ in indexed:
                        bycell[pi][idx].append(pid)

    anchor_forms = []
    for form in orients[anchor]:
        if form.get((0, 0)) == 5:
            anchor_forms.append(form)

    def search(occ, used, chosen):
        if occ == full:
            return chosen if used == (1 << len(pieces)) - 1 else None

        empty = full ^ occ
        best = None
        best_options = None
        bits = empty
        while bits:
            bit = bits & -bits
            idx = bit.bit_length() - 1
            options = []
            for pi in range(len(pieces)):
                if used & (1 << pi):
                    continue
                for pid in bycell[pi][idx]:
                    mask, indexed = placements[pi][pid]
                    if not (mask & occ):
                        options.append((pi, pid))
            if not options:
                return None
            if best_options is None or len(options) < len(best_options):
                best, best_options = idx, options
                if len(options) == 1:
                    break
            bits -= bit

        for pi, pid in best_options:
            mask, _ = placements[pi][pid]
            ans = search(occ | mask, used | (1 << pi), chosen + [(pi, pid)])
            if ans is not None:
                return ans
        return None

    marked = pieces[anchor][1]
    for form in anchor_forms:
        # The marker must be the upper-left cell of the output.
        entries = tuple(sorted((r, c, v) for (r, c), v in form.items()))
        mask = 0
        indexed = []
        valid = True
        for r, c, v in entries:
            if r >= n or c >= n:
                valid = False
                break
            idx = r * n + c
            mask |= 1 << idx
            indexed.append((idx, v))
        if not valid:
            continue

        # Find this anchored placement among the precomputed placements.
        pid = None
        for j, (pmask, pindexed) in enumerate(placements[anchor]):
            if pmask == mask and pindexed == indexed:
                pid = j
                break
        if pid is None:
            # The sorted placement may differ only in tuple ordering.
            for j, (pmask, pindexed) in enumerate(placements[anchor]):
                if pmask == mask and dict(pindexed) == dict(indexed):
                    pid = j
                    break
        if pid is None:
            continue

        ans = search(mask, 1 << anchor, [(anchor, pid)])
        if ans is not None:
            out = [[0] * n for _ in range(n)]
            for pi, p in ans:
                _, indexed_cells = placements[pi][p]
                for idx, val in indexed_cells:
                    out[idx // n][idx % n] = val
            return out

    return [row[:] for row in grid]

def transform(grid):
    from collections import Counter, defaultdict, deque

    h, w = len(grid), len(grid[0])
    colors = set(v for row in grid for v in row)
    candidates = []

    for color in colors:
        cells = [(r, c) for r in range(h) for c in range(w)
                 if grid[r][c] == color]
        if not cells:
            continue
        r0 = min(r for r, c in cells)
        r1 = max(r for r, c in cells)
        c0 = min(c for r, c in cells)
        c1 = max(c for r, c in cells)
        hh, ww = r1 - r0 + 1, c1 - c0 + 1
        area = hh * ww
        if hh < 5 or ww < 5 or area > 400:
            continue
        if any(grid[r0][c] != color or grid[r1][c] != color
               for c in range(c0, c1 + 1)):
            continue
        if any(grid[r][c0] != color or grid[r][c1] != color
               for r in range(r0, r1 + 1)):
            continue
        density = sum(grid[r][c] == color
                      for r in range(r0, r1 + 1)
                      for c in range(c0, c1 + 1)) / area
        if density >= 0.5:
            candidates.append((area, r0, c0, r1, c1, color))

    if not candidates:
        return [row[:] for row in grid]

    _, r0, c0, r1, c1, base = min(candidates)
    out = [row[c0:c1 + 1] for row in grid[r0:r1 + 1]]
    H, W = len(out), len(out[0])

    counts = Counter(v for row in out for v in row)
    holes = [v for v in counts if v != base]
    if not holes:
        return out
    hole_color = max(holes, key=counts.get)

    def components(cells):
        remaining = set(cells)
        result = []
        while remaining:
            start = remaining.pop()
            comp = {start}
            q = [start]
            while q:
                r, c = q.pop()
                for p in ((r-1,c), (r+1,c), (r,c-1), (r,c+1)):
                    if p in remaining:
                        remaining.remove(p)
                        comp.add(p)
                        q.append(p)
            result.append(comp)
        return result

    def shape_key(comp):
        pts = list(comp)
        variants = []
        for flip in (1, -1):
            for rot in range(4):
                transformed = []
                for r, c in pts:
                    x, y = r, flip * c
                    for _ in range(rot):
                        x, y = y, -x
                    transformed.append((x, y))
                mr = min(x for x, y in transformed)
                mc = min(y for x, y in transformed)
                variants.append(tuple(sorted((x-mr, y-mc)
                                             for x, y in transformed)))
        return min(variants)

    target = []
    for comp in components({(r, c) for r in range(H) for c in range(W)
                            if out[r][c] == hole_color}):
        target.append((comp, shape_key(comp)))

    # Collect colored objects outside the patterned rectangle.
    outside = defaultdict(list)
    for color in colors - {base, hole_color}:
        cells = {(r, c) for r in range(h) for c in range(w)
                 if grid[r][c] == color and
                 not (r0 <= r <= r1 and c0 <= c <= c1)}
        for comp in components(cells):
            outside[shape_key(comp)].append((color, comp))

    for comp, key in target:
        matches = outside.get(key, [])
        if not matches:
            continue
        votes = Counter(color for color, _ in matches)
        chosen = votes.most_common(1)[0][0]
        for r, c in comp:
            out[r][c] = chosen

    return out

def transform(grid):
    from collections import Counter, deque

    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = Counter(v for row in grid for v in row)
    structural = {v for v, _ in counts.most_common(2)}
    background = counts.most_common(1)[0][0]
    panel_color = next((v for v in structural if v != background), None)

    # Extract the ordered color sequence from the key row.
    scores = [sum(v not in structural for v in row) for row in grid]
    key_row = max(range(h), key=lambda r: (scores[r], r))
    sequence = [v for v in grid[key_row] if v not in structural]

    # Find the colored 2x2 objects.
    seen = [[False] * w for _ in range(h)]
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color in structural or seen[r][c]:
                continue
            q = [(r, c)]
            seen[r][c] = True
            cells = []
            while q:
                y, x = q.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and not seen[ny][nx]
                            and grid[ny][nx] == color):
                        seen[ny][nx] = True
                        q.append((ny, nx))
            ys = [y for y, _ in cells]
            xs = [x for _, x in cells]
            if len(cells) == 4 and max(ys) - min(ys) == 1 and max(xs) - min(xs) == 1:
                objects.append({
                    "color": color, "top": min(ys), "bottom": max(ys),
                    "left": min(xs), "right": max(xs)
                })

    if not objects or panel_color is None:
        return out

    # Find the rectangular panel surrounding each object.
    seen_panel = [[False] * w for _ in range(h)]
    panels = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != panel_color or seen_panel[r][c]:
                continue
            q = [(r, c)]
            seen_panel[r][c] = True
            cells = []
            while q:
                y, x = q.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and not seen_panel[ny][nx]
                            and grid[ny][nx] == panel_color):
                        seen_panel[ny][nx] = True
                        q.append((ny, nx))
            panels.append((min(y for y, _ in cells), max(y for y, _ in cells),
                           min(x for _, x in cells), max(x for _, x in cells)))

    for obj in objects:
        containing = [p for p in panels
                      if p[0] <= obj["top"] and p[1] >= obj["bottom"]
                      and p[2] <= obj["left"] and p[3] >= obj["right"]]
        if containing:
            obj["panel"] = min(containing, key=lambda p: (p[1]-p[0]+1)*(p[3]-p[2]+1))
        else:
            obj["panel"] = (obj["top"], obj["bottom"], obj["left"], obj["right"])

    # Adjacent objects in a shared row or column are consecutive along that line.
    adjacent = set()
    for i, a in enumerate(objects):
        for j, b in enumerate(objects):
            if i == j:
                continue
            if a["top"] == b["top"]:
                line = sorted((k for k, o in enumerate(objects) if o["top"] == a["top"]),
                              key=lambda k: objects[k]["left"])
                if abs(line.index(i) - line.index(j)) == 1:
                    adjacent.add((i, j))
            if a["left"] == b["left"]:
                line = sorted((k for k, o in enumerate(objects) if o["left"] == a["left"]),
                              key=lambda k: objects[k]["top"])
                if abs(line.index(i) - line.index(j)) == 1:
                    adjacent.add((i, j))

    candidates = [[i for i, obj in enumerate(objects) if obj["color"] == color]
                  for color in sequence]

    # Match the key sequence to a non-repeating path through the objects.
    path = []

    def search(pos, used):
        if pos == len(sequence):
            return True
        for i in candidates[pos]:
            if i in used:
                continue
            if pos and (path[-1], i) not in adjacent:
                continue
            path.append(i)
            used.add(i)
            if search(pos + 1, used):
                return True
            used.remove(i)
            path.pop()
        return False

    if not candidates or not search(0, set()):
        return out

    # Connect each object to the next, extending the source object's color
    # through the gap between their panels.
    for a_idx, b_idx in zip(path, path[1:]):
        a, b = objects[a_idx], objects[b_idx]
        ap, bp = a["panel"], b["panel"]
        color = a["color"]

        if a["top"] == b["top"]:
            rows = range(a["top"], a["bottom"] + 1)
            if ap[2] < bp[2]:
                cols = range(ap[3] + 1, bp[2])
            else:
                cols = range(bp[3] + 1, ap[2])
            for r in rows:
                for c in cols:
                    out[r][c] = color
        elif a["left"] == b["left"]:
            cols = range(a["left"], a["right"] + 1)
            if ap[0] < bp[0]:
                rows = range(ap[1] + 1, bp[0])
            else:
                rows = range(bp[1] + 1, ap[0])
            for r in rows:
                for c in cols:
                    out[r][c] = color

    return out

def transform(grid):
    h, w = len(grid), len(grid[0])

    # A separator row divides the source motifs from the placement masks.
    n = next(r for r, row in enumerate(grid) if 5 in row)
    step = n + 1

    motifs = {}
    blocks = []
    for start in range(0, w - n + 1, step):
        cells = [grid[r][c] for r in range(n) for c in range(start, start + n)]
        colors = {v for v in cells if v not in (0, 5)}
        if not colors:
            continue
        color = next(iter(colors))
        blocks.append(start)
        marker_row = 2 * n + 3
        marker_col = start + n // 2
        marker = grid[marker_row][marker_col]
        motifs[color] = (
            marker,
            [[grid[r][start + c] == color for c in range(n)] for r in range(n)]
        )

    out = [[0] * (n * n) for _ in range(n * n)]
    mask_start = n + 1

    for start in blocks:
        for i in range(n):
            for j in range(n):
                key = grid[mask_start + i][start + j]
                if key not in motifs:
                    continue
                marker, shape = motifs[key]
                for a in range(n):
                    for b in range(n):
                        if shape[a][b]:
                            out[i * n + a][j * n + b] = marker

    return out

