                if g[r][c] == 0:
                    g[r][c] = 1
                elif g[r][c] == 2:
                    g[r][c] = 0
        return g

    zeros = [(r, c) for r in range(h) for c in range(w) if g[r][c] == 0]
    twos = [(r, c) for r in range(h) for c in range(w) if g[r][c] == 2]
    if not zeros or not twos:
        return g

    r0 = min(r for r, c in zeros)
    r1 = max(r for r, c in zeros)
    c0 = min(c for r, c in zeros)
    c1 = max(c for r, c in zeros)
    rh, rw = r1 - r0 + 1, c1 - c0 + 1
    tr = min(r for r, c in twos)
    tc = min(c for r, c in twos)

    # Slide the rectangular zero piece through the non-wall cells.
    from collections import deque
    start = (r0, c0)

    def fits(r, c):
        return (0 <= r <= h - rh and 0 <= c <= w - rw and
                all(g[y][x] in (0, 1, 2)
                    for y in range(r, r + rh)
                    for x in range(c, c + rw)))

    seen = {start}
    q = deque([start])
    while q:
        r, c = q.popleft()
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            p = (r + dr, c + dc)
            if p not in seen and fits(*p):
                seen.add(p)
                q.append(p)

    dest = min(seen, key=lambda p: (abs(p[0] - tr) + abs(p[1] - tc),
                                    p[0], p[1]))
    for r, c in zeros:
        g[r][c] = 1
    for r in range(dest[0], dest[0] + rh):
        for c in range(dest[1], dest[1] + rw):
            g[r][c] = 0
    return g

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    components = []

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            grid[ny][nx] == 1 and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            components.append(comp)

    def extend(axis, start, direction, positions):
        positions = sorted(positions)
        groups = []
        for q in positions:
            if not groups or q > groups[-1][-1] + 1:
                groups.append([q])
            else:
                groups[-1].append(q)

        for group in groups:
            def cell_at(distance, q):
                if axis == 0:
                    y, x = start + direction * distance, q
                else:
                    y, x = q, start + direction * distance
                return (y, x) if 0 <= y < h and 0 <= x < w else None

            seed = []
            distance = 0
            while True:
                cells = [cell_at(distance, q) for q in group]
                if any(cell is None for cell in cells):
                    break
                values = tuple(grid[y][x] for y, x in cells)
                if any(v in (1, 8) for v in values):
                    break
                seed.append(values)
                distance += 1

            if not seed:
                continue

            period = len(seed)
            for p in range(1, min(6, len(seed)) + 1):
                errors = sum(seed[i] != seed[i % p] for i in range(len(seed)))
                if errors / len(seed) <= 0.20:
                    period = p
                    break

            distance = 0
            while True:
                cells = [cell_at(distance, q) for q in group]
                if any(cell is None for cell in cells):
                    break
                if any(grid[y][x] == 1 for y, x in cells):
                    break
                pattern = seed[distance % period]
                for (y, x), value in zip(cells, pattern):
                    out[y][x] = value
                distance += 1

    for comp in components:
        min_r = min(r for r, c in comp)
        max_r = max(r for r, c in comp)
        min_c = min(c for r, c in comp)
        max_c = max(c for r, c in comp)

        top = {c for r, c in comp if r == min_r}
        bottom = {c for r, c in comp if r == max_r}
        left = {r for r, c in comp if c == min_c}
        right = {r for r, c in comp if c == max_c}

        for start, direction, cols in (
            (min_r - 1, -1, top),
            (max_r + 1, 1, bottom),
        ):
            if 0 <= start < h:
                active = [c for c in cols if grid[start][c] not in (1, 8)]
                if active:
                    extend(0, start, direction, active)

        for start, direction, rows in (
            (min_c - 1, -1, left),
            (max_c + 1, 1, right),
        ):
            if 0 <= start < w:
                active = [r for r in rows if grid[r][start] not in (1, 8)]
                if active:
                    extend(1, start, direction, active)

    return out

