def transform(grid):
    from collections import Counter, deque

    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    # The lower-left key pairs specify rectangle-marker color -> fill color.
    mapping = {}
    for r in range(h // 2, h):
        for c in range(min(4, w - 1)):
            a, b = grid[r][c], grid[r][c + 1]
            if a != bg and b != bg:
                mapping[a] = b

    # Find connected components that are L-shaped triominoes.
    seen = set()
    ls = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                x, y = q.popleft()
                cells.append((x, y))
                for nx, ny in ((x - 1, y), (x + 1, y),
                               (x, y - 1), (x, y + 1)):
                    if (0 <= nx < h and 0 <= ny < w and
                            (nx, ny) not in seen and grid[nx][ny] == color):
                        seen.add((nx, ny))
                        q.append((nx, ny))

            if len(cells) == 3:
                r0, r1 = min(x for x, _ in cells), max(x for x, _ in cells)
                c0, c1 = min(y for _, y in cells), max(y for _, y in cells)
                if r1 - r0 == 1 and c1 - c0 == 1:
                    corners = {(x - r0, y - c0) for x, y in cells}
                    missing = next(iter({(0, 0), (0, 1), (1, 0), (1, 1)} - corners))
                    ls.append((color, missing, (r0, r1, c0, c1)))

    # Opposite-oriented Ls of the same color mark a rectangle.
    rectangles = []
    for i, (color, missing, box1) in enumerate(ls):
        for color2, missing2, box2 in ls[i + 1:]:
            if color != color2:
                continue
            if {missing, missing2} not in (
                    {(0, 0), (1, 1)}, {(0, 1), (1, 0)}):
                continue
            r0 = min(box1[0], box2[0])
            r1 = max(box1[1], box2[1])
            c0 = min(box1[2], box2[2])
            c1 = max(box1[3], box2[3])
            rectangles.append((color, (r0, r1, c0, c1)))

    # Unmapped marker rectangles are holes in other fills.
    holes = []
    fills = []
    for color, (r0, r1, c0, c1) in rectangles:
        if color not in mapping:
            holes.append((r0, r1, c0, c1))
            continue
        target = mapping[color]
        # Zero denotes no fill; painting the background color has no effect.
        if target == 0 or target == bg:
            continue
        fills.append(((r1 - r0 + 1) * (c1 - c0 + 1),
                      r0, r1, c0, c1, target))

    out = [row[:] for row in grid]
    # Paint larger rectangles first so smaller nested rectangles overlay them.
    for _, r0, r1, c0, c1, target in sorted(fills, reverse=True):
        for r in range(r0, r1 + 1):
            for c in range(c0, c1 + 1):
                if grid[r][c] != bg:
                    continue
                if any(a <= r <= b and x <= c <= y for a, b, x, y in holes):
                    continue
                out[r][c] = target

    return out

